    def test_get_metar_response_schema_validation(self, api_client):
        """Test response schema validation against OpenAPI spec"""
        params = {
            "ids": "KJFK",
            "format": "json",
            "hours": 1
        }
        
        response = api_client.get("/api/data/metar", params=params)
        
        assert response.status_code == 200
        data = response.json()
        
        if data:
            metar_item = data[0]
            
            # Required fields validation
            assert "icaoId" in metar_item
            assert isinstance(metar_item["icaoId"], str)
            
            assert "receiptTime" in metar_item
            assert isinstance(metar_item["receiptTime"], str)
            
            assert "obsTime" in metar_item
            assert isinstance(metar_item["obsTime"], int)
            
            assert "reportTime" in metar_item
            assert isinstance(metar_item["reportTime"], str)
            
            # Optional fields type validation
            if "temp" in metar_item:
                assert isinstance(metar_item["temp"], (int, float))
            
            if "wspd" in metar_item:
                assert isinstance(metar_item["wspd"], int)
                assert metar_item["wspd"] >= 0
            
            if "wgst" in metar_item:
                assert isinstance(metar_item["wgst"], int)
                assert metar_item["wgst"] >= 0
            
            if "vertVis" in metar_item:
                assert isinstance(metar_item["vertVis"], int)
                assert metar_item["vertVis"] >= 0
            
            if "clouds" in metar_item:
                assert isinstance(metar_item["clouds"], list)
                if metar_item["clouds"]:
                    cloud = metar_item["clouds"][0]
                    assert "cover" in cloud
                    assert "base" in cloud
                    assert isinstance(cloud["cover"], str)
                    assert isinstance(cloud["base"], int)
    
    @pytest.mark.parametrize("station_ids", [
        "KJFK",
        "KJFK,KLGA",
        "KJFK,KLGA,KEWR,KTEB"
    ])
    def test_get_metar_multiple_stations(self, api_client, station_ids):
        """Test METAR retrieval with multiple station IDs"""
        params = {
            "ids": station_ids,
            "format": "json",
            "hours": 1
        }
        
        response = api_client.get("/api/data/metar", params=params)
        
        assert response.status_code == 200
        data = response.json()
        assert isinstance(data, list)
        
        if data:
            returned_stations = [item["icaoId"] for item in data]
            requested_stations = station_ids.split(",")
            
            for station in returned_stations:
                assert station in requested_stations
    
